    },
    # calories per unit
    "calories": {
        "Chicken_Breast": 136, "Tofu": 198, "Brown_Rice": 93, "Salmon": 269,
        "Greek_Yogurt": 121, "Steak": 80, "Avocado": 300, "Eggs": 99, "Quinoa": 87,
    },
    # minimum requirements (>=)
    "requirement": {"protein": 72, "carbs": 158, "calories": 1896},
}

