def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.FOODS = pyo.Set(initialize=d["foods"])
    model.NUTRIENTS = pyo.Set(initialize=d["nutrients"])

    # x[i]: amount of food i used (continuous, nonnegative)
    model.x = pyo.Var(model.FOODS, within=pyo.NonNegativeReals)

    # Objective: minimize total cost  (minimize)
    def obj_rule(m):
        return sum(d["cost"][i] * m.x[i] for i in m.FOODS)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Nutrient constraints: sum_i content[n][i] * x[i] >= requirement[n]  (>= at least)
    def nutrient_rule(m, n):
        return sum(d[n][i] * m.x[i] for i in m.FOODS) >= d["requirement"][n]

    model.nutrient = pyo.Constraint(model.NUTRIENTS, rule=nutrient_rule)

    return model

import pyomo.environ as pyo

DATA = {
    "foods": [
        "Chicken Breast", "Tofu", "Brown Rice", "Salmon", "Greek Yogurt",
        "Steak", "Avocado", "Eggs", "Quinoa",
    ],
    "cost": {
        "Chicken Breast": 3,
        "Tofu": 2,
        "Brown Rice": 2,
        "Salmon": 6,
        "Greek Yogurt": 6,
        "Steak": 10,
        "Avocado": 7,
        "Eggs": 5,
        "Quinoa": 2,
    },
    "protein": {
        "Chicken Breast": 17, "Tofu": 15, "Brown Rice": 1, "Salmon": 11,
        "Greek Yogurt": 15, "Steak": 12, "Avocado": 4, "Eggs": 16, "Quinoa": 11,
    },
    "carbs": {
        "Chicken Breast": 28, "Tofu": 11, "Brown Rice": 11, "Salmon": 3,
        "Greek Yogurt": 27, "Steak": 3, "Avocado": 8, "Eggs": 25, "Quinoa": 20,
    },
    "calories": {
        "Chicken Breast": 136, "Tofu": 198, "Brown Rice": 93, "Salmon": 269,
        "Greek Yogurt": 121, "Steak": 80, "Avocado": 300, "Eggs": 99, "Quinoa": 87,
    },
    "req_protein": 72,
    "req_carbs": 158,
    "req_calories": 1896,
}


def build_model(data=None):
    d = data or DATA
    foods = d["foods"]

    model = pyo.ConcreteModel()
    model.FOODS = pyo.Set(initialize=foods)

    model.x = pyo.Var(model.FOODS, within=pyo.NonNegativeReals, bounds=(0, None))

    def cost_rule(m):
        return sum(d["cost"][i] * m.x[i] for i in m.FOODS)

    model.obj = pyo.Objective(expr=cost_rule(model), sense=pyo.minimize)

    def protein_rule(m):
        return sum(d["protein"][i] * m.x[i] for i in m.FOODS) >= d["req_protein"]

    model.protein_req = pyo.Constraint(expr=protein_rule(model))

    def carbs_rule(m):
        return sum(d["carbs"][i] * m.x[i] for i in m.FOODS) >= d["req_carbs"]

    model.carbs_req = pyo.Constraint(expr=carbs_rule(model))

    def calories_rule(m):
        return sum(d["calories"][i] * m.x[i] for i in m.FOODS) >= d["req_calories"]

    model.calories_req = pyo.Constraint(expr=calories_rule(model))

    return model


